#!/usr/bin/env node
// floorplan/serve.mjs: serve this map locally and answer questions about the codebase through Kimi Code.
// Generated by build.mjs; needs only Node 18+ and a logged-in `kimi` CLI.
//
// usage: node floorplan/serve.mjs [--port 4378] [--model <model>] [--kimi <path to kimi>] [--no-open] [--idle-exit <minutes>]
//        node floorplan/serve.mjs --stop
//
// The server listens on 127.0.0.1 only. Questions use a custom Kimi agent restricted to Read, Grep and Glob.
// When the map is rebuilt, open tabs reload in place. The running server is recorded in .cache/server.json.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawn, execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const realHere = fs.realpathSync(here);
const root = path.resolve(here, '..');
const argv = process.argv.slice(2);
const opt = (name, dflt) => { const i = argv.indexOf('--' + name); return i < 0 ? dflt : argv[i + 1]; };
const has = (name) => argv.includes('--' + name);
const stateFile = path.join(here, '.cache', 'server.json');
const readState = () => { try { return JSON.parse(fs.readFileSync(stateFile, 'utf8')); } catch { return null; } };
if (has('stop')) {
  const s = readState();
  let stopped = false;
  if (s?.pid) { try { process.kill(s.pid); stopped = true; } catch {} }
  try { fs.unlinkSync(stateFile); } catch {}
  console.log(stopped ? `Stopped the map server (${s.url}).` : 'The map server was not running.');
  process.exit(0);
}
const wantPort = Number(opt('port', 4378));
const idleExit = Number(opt('idle-exit', 0)) * 60000;
const selfHash = crypto.createHash('sha1').update(fs.readFileSync(fileURLToPath(import.meta.url))).digest('hex').slice(0, 12);
const model = opt('model', process.env.FLOORPLAN_MODEL || '');
const token = crypto.randomBytes(16).toString('hex');
const TYPES = { '.html': 'text/html; charset=utf-8', '.json': 'application/json', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml' };

function which(cmd) {
  try {
    const out = execFileSync(process.platform === 'win32' ? 'where' : 'which', [cmd], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    return out.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
  } catch { return []; }
}
/** Returns { cmd, args } to spawn, or null. Handles native installs and JavaScript entry points. */
function resolveKimi() {
  const explicit = opt('kimi', process.env.FLOORPLAN_KIMI);
  const candidates = explicit ? [explicit] : [
    ...which('kimi'),
    path.join(process.env.HOME || process.env.USERPROFILE || '', '.local', 'bin', process.platform === 'win32' ? 'kimi.exe' : 'kimi'),
  ];
  for (const c of candidates) {
    if (!c || !fs.existsSync(c)) continue;
    if (/\.(m?js)$/i.test(c)) return { cmd: process.execPath, args: [c], path: c };
    // Shell shims would make prompt text shell input, bypassing the read-only agent boundary.
    if (/\.(cmd|bat|ps1)$/i.test(c)) continue;
    return { cmd: c, args: [], path: c };
  }
  return null;
}
const kimi = resolveKimi();
let version = null;
if (kimi) { try { version = execFileSync(kimi.cmd, [...kimi.args, '--version'], { encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true }).trim(); } catch {} }

const inject = `<script>window.FLOORPLAN_SERVER=${JSON.stringify({ token, cli: !!kimi, version, model: model || null })};</script>`;
let page, G, core, MODES, loadVersion = 0;
const agentFile = path.join(here, '.cache', 'kimi-agent.md');
const AGENT = `---
name: floorplan-readonly
description: Answer questions about an architecture map without changing the project
tools:
  - Read
  - Grep
  - Glob
subagents: []
---

You answer questions about a codebase and its architecture map. Follow the requested output format exactly.
You are read-only: never create, edit or delete files, never run shell commands, and never delegate work.
Read the context file named in the user's prompt before exploring source files. Your final message must contain only the requested JSON.
`;
function mapContext(q) {
  const all = [
    ...G.nodes.map((n) => q.brief('n:' + n.id)),
    ...G.files.map((f) => q.brief('f:' + f.p)),
    ...(G.routes || []).map((_, i) => q.brief('r:' + i)),
    ...G.files.flatMap((f) => (f.s || []).map((_, i) => q.brief(`s:${f.p}#${i}`))),
  ].filter(Boolean);
  const items = [];
  for (const item of all) {
    if (items.length && JSON.stringify(items).length + JSON.stringify(item).length > 100000) break;
    items.push(item);
  }
  return JSON.stringify({ overview: q.overview(), items, truncated: items.length < all.length }, null, 2);
}
async function load() {
  const html = fs.readFileSync(path.join(here, 'index.html'), 'utf8');
  const g = JSON.parse(fs.readFileSync(path.join(here, 'graph.json'), 'utf8'));
  const moduleUrl = pathToFileURL(path.join(here, 'graph-query.mjs')).href + '?floorplan=' + ++loadVersion;
  const c = await import(moduleUrl);
  const q = c.createGraphQuery(g);
  page = html.replace('</head>', inject + '</head>');
  G = g; core = { ...c, q };
  fs.mkdirSync(path.dirname(agentFile), { recursive: true });
  fs.writeFileSync(agentFile, AGENT);
  const context = mapContext(q);
  MODES = {
    ask: { instructions: core.floorplanAskInstructions(G), schema: JSON.stringify(core.FLOORPLAN_ANSWER_SCHEMA), context },
    flow: { instructions: core.floorplanFlowInstructions(G), schema: JSON.stringify(core.FLOORPLAN_FLOW_SCHEMA), context },
  };
  for (const [name, mode] of Object.entries(MODES)) {
    mode.file = path.join(here, '.cache', `kimi-${name}-context.md`);
    fs.writeFileSync(mode.file, `${mode.instructions}\n\nThe JSON must match this schema:\n${mode.schema}\n\nMap context:\n${mode.context}\n`);
    mode.relativeFile = path.relative(root, mode.file).replace(/\\/g, '/');
  }
}
await load();

// ---------- open tabs: live reload, and idle shutdown ----------
const tabs = new Set();
let lastTab = Date.now();
const broadcast = (event, data = {}) => { for (const t of tabs) t.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); };
let reloadTimer = null;
fs.watchFile(path.join(here, 'index.html'), { interval: 1000 }, (cur, prev) => {
  if (cur.mtimeMs === prev.mtimeMs) return;
  clearTimeout(reloadTimer);
  reloadTimer = setTimeout(async () => {
    try { await load(); broadcast('reload'); console.log('map rebuilt: reloaded open tabs'); } catch {}
  }, 800);
});
if (idleExit) setInterval(() => { if (!tabs.size && !running.size && Date.now() - lastTab > idleExit) process.exit(0); }, 60000).unref();
const flowsFile = path.join(here, 'custom-flows.json');
const readFlows = () => { try { return JSON.parse(fs.readFileSync(flowsFile, 'utf8')).flows || []; } catch { return []; } };

// ---------- asking ----------
const running = new Map();
function describeTool(name, input = {}) {
  const rel = (p) => String(p || '').replace(/\\/g, '/').replace(root.replace(/\\/g, '/') + '/', '');
  if (name === 'Read') return `Reading ${rel(input.path || input.file_path)}`;
  if (name === 'Grep') return `Searching code for "${input.pattern}"`;
  if (name === 'Glob') return `Listing ${input.pattern}`;
  return name;
}
function textContent(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.map((part) => typeof part === 'string' ? part : part?.text || part?.content || '').join('');
}
function parseAnswer(text) {
  const t = String(text || '').trim();
  const fence = /```(?:json)?\s*([\s\S]*?)```/.exec(t);
  const candidates = [t, fence?.[1], t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)];
  for (const cand of candidates) {
    try { const value = JSON.parse(cand); if (value && typeof value === 'object' && !Array.isArray(value)) return value; } catch {}
  }
  return { title: 'Answer', answer: t, items: [] };
}
function ask(req, res, body) {
  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive' });
  const send = (event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  if (!kimi) { send('failure', { code: 'cli_missing', message: 'Kimi Code CLI not found.' }); return res.end(); }
  const mode = MODES[body.mode] || MODES.ask;
  const question = String(body.question || '').slice(0, 4000);
  const prompt = body.session ? question : `Read ${mode.relativeFile} and follow its instructions. Answer this question: ${question}`;
  const args = [...kimi.args];
  if (body.session) args.push('--session', String(body.session));
  else args.push('--agent-file', agentFile);
  args.push('-p', prompt, '--output-format', 'stream-json');
  if (model) args.push('--model', model);
  const child = spawn(kimi.cmd, args, { cwd: root, env: process.env, stdio: ['ignore', 'pipe', 'pipe'], windowsHide: true });
  const id = crypto.randomBytes(6).toString('hex');
  running.set(id, child);
  send('start', { id });
  let buf = '', stderr = '', answerText = '', session = null, done = false;
  const fail = (code, message) => { if (done) return; done = true; send('failure', { code, message }); res.end(); };
  child.stdout.on('data', (d) => {
    buf += d;
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl).trim(); buf = buf.slice(nl + 1);
      if (!line) continue;
      let ev; try { ev = JSON.parse(line); } catch { continue; }
      session = ev.session_id || ev.sessionId || session;
      if (ev.role !== 'assistant') continue;
      const text = textContent(ev.content);
      if (text.trim()) answerText = text;
      for (const call of ev.tool_calls || []) {
        const fn = call.function || call;
        let input = fn.arguments ?? fn.input ?? call.input ?? {};
        if (typeof input === 'string') { try { input = JSON.parse(input); } catch { input = {}; } }
        send('progress', { text: describeTool(fn.name || call.name, input) });
      }
    }
  });
  child.stderr.on('data', (d) => { stderr = (stderr + d).slice(-4000); });
  child.on('error', (e) => fail('cli_error', e.message));
  child.on('close', (code) => {
    running.delete(id);
    if (done) return;
    if (code === 0 && answerText.trim()) {
      done = true;
      send('answer', { ...parseAnswer(answerText), session });
      res.end();
      return;
    }
    const message = stderr.trim() || `kimi exited with code ${code}`;
    fail(/not logged in|\/login|authenticat|unauthorized|\b401\b/i.test(message) ? 'not_logged_in' : 'cli_error', message);
  });
  res.on('close', () => { if (!done) child.kill(); });
}

// ---------- http ----------
function staticFile(pathname) {
  let decoded;
  try { decoded = decodeURIComponent(pathname); } catch { return { error: 400 }; }
  if (decoded.includes('\0')) return { error: 400 };
  const candidate = path.resolve(here, '.' + (decoded.startsWith('/') ? decoded : '/' + decoded));
  const relative = path.relative(here, candidate);
  if (!relative || relative === '..' || relative.startsWith('..' + path.sep) || path.isAbsolute(relative)) return { error: 404 };
  try {
    const file = fs.realpathSync(candidate);
    const realRelative = path.relative(realHere, file);
    if (!realRelative || realRelative === '..' || realRelative.startsWith('..' + path.sep) || path.isAbsolute(realRelative) || !fs.statSync(file).isFile()) return { error: 404 };
    return { file };
  } catch { return { error: 404 }; }
}
const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const sameOrigin = !req.headers.origin || req.headers.origin === `http://${req.headers.host}`;
  if (url.pathname.startsWith('/api/')) {
    const given = req.headers['x-floorplan-token'];
    if (!sameOrigin || given !== token) { res.writeHead(403); return res.end(); }
    if (req.method === 'GET' && url.pathname === '/api/events') {
      res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive' });
      res.write('retry: 1000\n\n');
      tabs.add(res);
      req.on('close', () => { tabs.delete(res); lastTab = Date.now(); });
      return;
    }
    if (req.method === 'GET' && url.pathname === '/api/status') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ tabs: tabs.size, pid: process.pid, hash: selfHash, root })); }
    if (req.method === 'GET' && url.pathname === '/api/health') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ cli: !!kimi, version, path: kimi?.path || null })); }
    if (url.pathname === '/api/flows') {
      if (req.method === 'GET') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ flows: readFlows() })); }
      if (req.method === 'POST' || req.method === 'DELETE') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 50000) req.destroy(); });
        req.on('end', () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          let flows = readFlows().filter((x) => x.id !== body.id && x.id !== body.flow?.id);
          if (req.method === 'POST' && body.flow?.id && Array.isArray(body.flow.steps)) flows.push({ ...body.flow, createdAt: new Date().toISOString() });
          fs.writeFileSync(flowsFile, JSON.stringify({ flows }, null, 2) + '\n');
          res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ flows }));
        });
        return;
      }
    }
    if (req.method === 'POST' && url.pathname === '/api/cancel') { for (const c of running.values()) c.kill(); res.writeHead(204); return res.end(); }
    if (req.method === 'POST' && url.pathname === '/api/ask') {
      let raw = '';
      req.on('data', (d) => { raw += d; if (raw.length > 20000) req.destroy(); });
      req.on('end', () => { let body = {}; try { body = JSON.parse(raw); } catch {} ask(req, res, body); });
      return;
    }
    res.writeHead(404); return res.end();
  }
  if (url.pathname === '/' || url.pathname === '/index.html') { res.writeHead(200, { 'Content-Type': TYPES['.html'], 'Cache-Control': 'no-store' }); return res.end(page); }
  const found = staticFile(url.pathname);
  if (found.error) { res.writeHead(found.error); return res.end(found.error === 400 ? 'bad address' : 'not found'); }
  res.writeHead(200, { 'Content-Type': TYPES[path.extname(found.file)] || 'application/octet-stream' });
  fs.createReadStream(found.file).pipe(res);
});
let port = wantPort;
server.on('error', (e) => {
  if (e.code === 'EADDRINUSE' && port < wantPort + 20) { port++; server.listen(port, '127.0.0.1'); return; }
  console.error(`✗ Couldn't start the map server: ${e.message}`);
  process.exit(1);
});
server.listen(port, '127.0.0.1');
server.on('listening', () => {
  const u = `http://127.0.0.1:${port}`;
  try {
    fs.mkdirSync(path.dirname(stateFile), { recursive: true });
    fs.writeFileSync(stateFile, JSON.stringify({ pid: process.pid, port, url: u, token, hash: selfHash, startedAt: new Date().toISOString() }, null, 2));
  } catch {}
  const forget = () => { try { if (readState()?.pid === process.pid) fs.unlinkSync(stateFile); } catch {} };
  process.on('exit', forget);
  for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(sig, () => process.exit(0));
  console.log(`Floorplan: ${u}`);
  console.log(kimi ? `asking via Kimi Code CLI ${version || ''} (${kimi.path})${model ? `, model ${model}` : ''}` : 'Kimi Code CLI not found: the map works, but asking questions needs it (https://www.kimi.com/code/docs/en/). Pass --kimi <path> if it is installed somewhere unusual.');
  if (!has('no-open')) {
    const opener = process.platform === 'win32' ? ['cmd', ['/c', 'start', '', u]] : process.platform === 'darwin' ? ['open', [u]] : ['xdg-open', [u]];
    try { spawn(opener[0], opener[1], { stdio: 'ignore', detached: true }).unref(); } catch {}
  }
});
